import 'package:flutter/material.dart';
import '../services/api.dart';
import '../theme.dart';
import 'tuition_page.dart';

class OmniraPage extends StatefulWidget {
  final String name;
  final Api api;
  final Map<String,dynamic> user;
  final ValueChanged<String> onNavigate;
  const OmniraPage({super.key,required this.name,required this.api,required this.user,required this.onNavigate});
  @override State<OmniraPage> createState()=>_OmniraPageState();
}
class _OmniraPageState extends State<OmniraPage> {
  dynamic data;
  bool loading=true;
  String? error;
  final filename=TextEditingController();
  final pages=TextEditingController(text:'1');
  final copies=TextEditingController(text:'1');
  final note=TextEditingController();
  final subject=TextEditingController();
  final maintenanceNote=TextEditingController();
  int? selectedComputer;
  DateTime? start;
  DateTime? end;
  @override void initState(){super.initState();load();}
  @override void dispose(){for(final c in [filename,pages,copies,note,subject,maintenanceNote]){c.dispose();}super.dispose();}
  Future<void> load() async {setState((){loading=true;error=null;});try{final path=switch(widget.name){'Home'=>'/dashboard','Computers'=>'/computers','Reservations'=>'/reservations','Sessions'=>'/sessions','Printing'=>'/printing','Payments'=>'/payments','Maintenance'=>'/maintenance','Analytics'=>'/analytics',_=>''};final result=path.isEmpty?null:await widget.api.get(path);if(mounted)setState(()=>data=result);}catch(e){if(mounted)setState(()=>error='$e');}finally{if(mounted)setState(()=>loading=false);}}
  Future<void> act(Future<dynamic> Function() run,{String success='Saved'}) async {try{final result=await run();if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(result is Map && result['amount']!=null?'$success · ₱${result['amount']}':success)));await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}
  Widget panel(Widget child)=>Card(margin:const EdgeInsets.only(bottom:14),child:Padding(padding:const EdgeInsets.all(18),child:child));
  Widget heading(String text)=>Padding(padding:const EdgeInsets.only(bottom:12),child:Text(text,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:navy)));
  Widget entry(String title,String subtitle,{Widget? trailing,VoidCallback? onTap})=>panel(ListTile(contentPadding:EdgeInsets.zero,title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(subtitle),trailing:trailing,onTap:onTap));
  Widget field(TextEditingController c,String label,{TextInputType? keyboard,int lines=1})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,keyboardType:keyboard,maxLines:lines,decoration:InputDecoration(labelText:label)));
  Widget action(String label,VoidCallback callback)=>SizedBox(width:double.infinity,child:FilledButton(onPressed:callback,child:Text(label)));
  @override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(18),children:[if(loading)const Center(child:CircularProgressIndicator())else if(error!=null)panel(Text('$error\nCheck that the API is running.'))else ...[if(widget.api.showingCachedData)panel(const Text('Offline · showing saved data. New campus transactions require a connection.')),...content()]]));
  List<Widget> content()=>switch(widget.name){'Home'=>home(),'Computers'=>computers(),'Reservations'=>reservations(),'Sessions'=>sessions(),'Printing'=>printing(),'Payments'=>payments(),'Maintenance'=>maintenance(),'Analytics'=>analytics(),_=>reviewer()};
  List<Widget> home(){final d=Map<String,dynamic>.from(data);final links=widget.user['role']=='student'?['Computers','Reservations','Sessions','Printing','Payments','AI Reviewer']:widget.user['role']=='professor'?['Reservations','Printing','Analytics','AI Reviewer']:['Computers','Reservations','Sessions','Printing','Maintenance','Analytics'];return [Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[navy,Color(0xFF346493)]),borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('OMNIRA',style:TextStyle(color:sky,letterSpacing:2,fontWeight:FontWeight.bold)),const SizedBox(height:16),Text('Good day, ${widget.user['name']}!',style:const TextStyle(fontSize:23,color:Colors.white,fontWeight:FontWeight.bold)),const SizedBox(height:10),const Text('Your campus workspace is ready.',style:TextStyle(color:Colors.white70))])),const SizedBox(height:20),Wrap(spacing:10,runSpacing:10,children:[metric(d['available_computers'],'Available PCs',Icons.computer),metric(d['reservations'],'Bookings',Icons.event),metric(d['active_sessions'],'Active sessions',Icons.timer),metric(d['open_print_jobs'],'Print jobs',Icons.print)]),const SizedBox(height:18),heading('Quick access'),...links.map((s)=>entry(s,'Open $s',trailing:const Icon(Icons.chevron_right),onTap:()=>widget.onNavigate(s)))];}
  Widget metric(dynamic number,String label,IconData icon)=>Container(width:MediaQuery.sizeOf(context).width>900?210:(MediaQuery.sizeOf(context).width-46)/2,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:orange),const SizedBox(height:14),Text('$number',style:const TextStyle(fontSize:27,fontWeight:FontWeight.bold,color:navy)),Text(label,style:const TextStyle(color:Colors.grey))]));
  List<Widget> computers()=>[heading('Computer availability'),...((data as List).map((pc)=>entry('${pc['label']} · ${pc['lab']}',pc['status'],trailing:Icon(pc['status']=='available'?Icons.check_circle:Icons.build_circle,color:pc['status']=='available'?sky:orange))))];
  List<Widget> reservations()=>[if(widget.user['role']=='student')panel(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[heading('Reserve a computer'),FutureBuilder<dynamic>(future:widget.api.get('/computers'),builder:(context,snapshot){if(!snapshot.hasData)return const LinearProgressIndicator();final available=(snapshot.data as List).where((pc)=>pc['status']=='available').toList();selectedComputer??=available.isNotEmpty?available.first['id'] as int:null;return DropdownButtonFormField<int>(value:selectedComputer,items:available.map<DropdownMenuItem<int>>((pc)=>DropdownMenuItem(value:pc['id'] as int,child:Text('${pc['label']} · ${pc['lab']}'))).toList(),onChanged:(v)=>setState(()=>selectedComputer=v),decoration:const InputDecoration(labelText:'Computer'));}),const SizedBox(height:12),ListTile(title:Text(start==null?'Start date and time':start.toString().substring(0,16)),leading:const Icon(Icons.schedule),onTap:()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:90)),initialDate:DateTime.now());if(d==null||!context.mounted)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.now());if(t!=null)setState(()=>start=DateTime(d.year,d.month,d.day,t.hour,t.minute));}),ListTile(title:Text(end==null?'End date and time':end.toString().substring(0,16)),leading:const Icon(Icons.schedule),onTap:()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:90)),initialDate:start??DateTime.now());if(d==null||!context.mounted)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.now());if(t!=null)setState(()=>end=DateTime(d.year,d.month,d.day,t.hour,t.minute));}),action('Reserve now',()=>act(()=>widget.api.post('/reservations',{'computer_id':selectedComputer,'starts_at':start?.toUtc().toIso8601String(),'ends_at':end?.toUtc().toIso8601String()}),success:'Reservation confirmed'))])),heading('Bookings'),...((data as List).map((r)=>entry('${r['label']} · ${r['lab']}','${r['student']} · ${r['starts_at']}\n${r['status']}',trailing:r['status']=='confirmed'?IconButton(icon:const Icon(Icons.cancel_outlined),onPressed:()=>act(()=>widget.api.post('/reservations/${r['id']}/cancel'),success:'Cancelled')):null)))];
  List<Widget> sessions()=>[if(widget.user['role']!='professor')panel(Column(children:[heading('Start a lab session'),FutureBuilder<dynamic>(future:widget.api.get('/computers'),builder:(context,snapshot){if(!snapshot.hasData)return const LinearProgressIndicator();final available=(snapshot.data as List).where((pc)=>pc['status']=='available').toList();selectedComputer??=available.isNotEmpty?available.first['id'] as int:null;return DropdownButtonFormField<int>(value:selectedComputer,items:available.map<DropdownMenuItem<int>>((pc)=>DropdownMenuItem(value:pc['id'] as int,child:Text('${pc['label']} · ${pc['lab']}'))).toList(),onChanged:(v)=>setState(()=>selectedComputer=v),decoration:const InputDecoration(labelText:'Computer'));}),const SizedBox(height:12),action('Start session',()=>act(()=>widget.api.post('/sessions/start',{'computer_id':selectedComputer}),success:'Session started'))])),heading('Lab sessions'),...((data as List).map((s)=>entry('${s['label']} · ${s['student']}','Started ${s['started_at']} · ₱${s['amount']}',trailing:s['ended_at']==null?TextButton(onPressed:()=>act(()=>widget.api.post('/sessions/${s['id']}/end'),success:'Session ended'),child:const Text('End')):const Icon(Icons.check_circle,color:sky))))];
  List<Widget> printing()=>[if(widget.user['role']!='admin')panel(Column(children:[heading('Print request'),field(filename,'Filename'),field(pages,'Pages',keyboard:TextInputType.number),field(copies,'Copies',keyboard:TextInputType.number),action('Submit request',()=>act(()=>widget.api.post('/printing',{'filename':filename.text,'pages':int.tryParse(pages.text),'copies':int.tryParse(copies.text)}),success:'Request saved'))])),heading('Print jobs'),...((data as List).map((j)=>entry(j['filename'],'${j['pages']} pages × ${j['copies']} · ₱${j['amount']} · ${j['status']}',trailing:widget.user['role']=='admin'&&j['status']=='pending'?TextButton(onPressed:()=>act(()=>widget.api.post('/printing/${j['id']}/complete'),success:'Completed'),child:const Text('Complete')):null)))];
  List<Widget> payments()=>[if(widget.user['role']=='student')TuitionBalanceCard(api:widget.api),heading('Payments and receipts'),FutureBuilder<List<dynamic>>(future:Future.wait([widget.api.get('/sessions'),widget.api.get('/printing')]),builder:(context,snapshot){if(!snapshot.hasData)return const LinearProgressIndicator();final paid=(data as List);final bills=[...(snapshot.data![0] as List).where((s)=>s['ended_at']!=null&&!paid.any((p)=>p['item_type']=='session'&&p['item_id']==s['id'])).map((s)=>{'type':'session','id':s['id'],'title':'Lab session ${s['label']}','amount':s['amount']}),...(snapshot.data![1] as List).where((j)=>!paid.any((p)=>p['item_type']=='print'&&p['item_id']==j['id'])).map((j)=>{'type':'print','id':j['id'],'title':'Printing ${j['filename']}','amount':j['amount']})];return Column(children:[...bills.map((b)=>entry('${b['title']}','₱${b['amount']}',trailing:widget.user['role']=='student'?TextButton(onPressed:()=>act(()=>widget.api.post('/payments',{'item_type':b['type'],'item_id':b['id'],'method':'demo_qr'}),success:'Demo payment recorded'),child:const Text('Demo QR Pay')):null)),if(bills.isEmpty)panel(const Text('No unpaid bills'))]);}),heading('Receipt history'),...((data as List).map((p)=>entry('OM-DEMO-${p['id']}','${p['item_type']} · ₱${p['amount']} · ${p['method']}',trailing:IconButton(icon:const Icon(Icons.receipt_long),onPressed:()async{final r=await widget.api.get('/receipts/${p['id']}');if(context.mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:Text(r['receipt_no']),content:Text('Amount: ₱${r['amount']}\n${r['note']}')));})))))];
  List<Widget> maintenance()=>[panel(Column(children:[heading('Log maintenance'),FutureBuilder<dynamic>(future:widget.api.get('/computers'),builder:(context,snapshot){if(!snapshot.hasData)return const LinearProgressIndicator();final pcs=snapshot.data as List;selectedComputer??=pcs.first['id'] as int;return DropdownButtonFormField<int>(value:selectedComputer,items:pcs.map<DropdownMenuItem<int>>((pc)=>DropdownMenuItem(value:pc['id'] as int,child:Text(pc['label']))).toList(),onChanged:(v)=>setState(()=>selectedComputer=v),decoration:const InputDecoration(labelText:'Computer'));}),const SizedBox(height:12),field(maintenanceNote,'Issue',lines:3),action('Save issue',()=>act(()=>widget.api.post('/maintenance',{'computer_id':selectedComputer,'note':maintenanceNote.text}),success:'Issue logged'))])),heading('Maintenance records'),...((data as List).map((m)=>entry(m['label'],m['note'])))];
  List<Widget> analytics()=>[metric(data['total_students'],'Students',Icons.people),const SizedBox(height:12),metric((data['total_lab_minutes'] as num).round(),'Lab minutes',Icons.timer),const SizedBox(height:18),panel(Text(data['note']))];
  List<Widget> reviewer()=>[heading('Offline reviewer preview'),panel(const Text('Create a rule-based reviewer from notes. A local AI model can be connected later.')),field(subject,'Subject'),field(note,'Lesson notes',lines:8),action('Generate reviewer',()async{try{final result=await widget.api.post('/reviewer',{'subject':subject.text,'notes':note.text});if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:Text(result['subject']),content:SingleChildScrollView(child:Text((result['reviewer'] as List).join('\n\n')))));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}})];
}
